"""Configuration management for CRM CLI - Base module."""

import json
import base64
import os
from pathlib import Path


# Stable task profiles must stay fixed even when a command changes cwd.
CONFIG_DIR = Path(os.environ['WENDING_CONFIG_DIR']) if os.environ.get('WENDING_CONFIG_DIR') else Path.cwd() / ".crm-cli"
CONFIG_FILE = CONFIG_DIR / "config.json"
THIRD_LOGIN_CONTEXT_PREFIX = "third_login_"
THIRD_LOGIN_CONTEXT_FIELDS = (
    "channel",
    "codeVerifier",
    "authTempCode",
    "token",
    "mobile",
    "wdid",
    "extInfo",
    "accountList",
    "selectedAccountId",
    "selectedChannel",
)

def ensure_config_dir():
    """Ensure config directory exists."""
    CONFIG_DIR.mkdir(parents=True, exist_ok=True)


def _encode_value(value: str) -> str:
    """Base64 encode a string value."""
    return base64.b64encode(value.encode("utf-8")).decode("utf-8")


def _decode_value(value: str) -> str:
    """Base64 decode a string value."""
    return base64.b64decode(value.encode("utf-8")).decode("utf-8")


def load_config() -> dict:
    """Load configuration from disk and decode values."""
    raw_config = {}
    if CONFIG_FILE.exists():
        with open(CONFIG_FILE, "r", encoding="utf-8") as f:
            raw_config = json.load(f)

    config = {}
    for key, value in raw_config.items():
        if isinstance(value, str):
            try:
                config[key] = _decode_value(value)
            except Exception:
                # 兼容未加密的旧配置
                config[key] = value
        else:
            config[key] = value
    shared = load_shared_auth()
    if shared.get('wnToken'):
        if config.get('stable_brand_id'):
            config.setdefault('stable_brand_channel', str(config.get('third_login_channel', '0')))
        config.update(shared)
    return config


def load_shared_auth():
    directory = os.environ.get('WENDING_SHARED_AUTH_DIR')
    if not directory: return {}
    file = Path(directory) / 'config.json'
    if not file.exists(): return {}
    try:
        raw = json.loads(file.read_text(encoding='utf-8'))
        decoded = {}
        for key in ('wnToken', 'third_login_channel'):
            if not isinstance(raw.get(key), str): continue
            try: decoded[key] = _decode_value(raw[key])
            except Exception: decoded[key] = raw[key]  # Legacy vendor plaintext format.
        return decoded
    except Exception:
        raise RuntimeError('共享登录配置无法读取，请在问鼎 CLI 表单重新检查。') from None


def save_shared_auth(token, channel):
    directory = os.environ.get('WENDING_SHARED_AUTH_DIR')
    if not directory: return
    import tempfile
    destination = Path(directory) / 'config.json'
    destination.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', dir=destination.parent, prefix='.stable-auth-', delete=False) as output:
            temporary = output.name
            json.dump({'wnToken': _encode_value(token), 'third_login_channel': _encode_value(channel)}, output)
            output.flush()
            os.fsync(output.fileno())
        os.replace(temporary, destination)
    finally:
        if temporary and os.path.exists(temporary): os.unlink(temporary)


def save_config(config: dict):
    """Save configuration to disk with encoded values."""
    ensure_config_dir()

    encoded_config = {}
    for key, value in config.items():
        if isinstance(value, str):
            encoded_config[key] = _encode_value(value)
        else:
            # 非字符串类型（如 dict, int, list）不加密
            encoded_config[key] = value

    with open(CONFIG_FILE, "w", encoding="utf-8") as f:
        json.dump(encoded_config, f, indent=2)


def set_auth(auth_data: dict):
    """Store auth credentials from login response.

    Args:
        auth_data: Complete auth data dict from login response
    """
    config = load_config()

    for key, value in auth_data.items():
        if value is not None:
            config[key] = value

    save_config(config)


def get_third_login_context() -> dict:
    """Load stored third login context from disk."""
    config = load_config()
    context = {}
    for field in THIRD_LOGIN_CONTEXT_FIELDS:
        key = f"{THIRD_LOGIN_CONTEXT_PREFIX}{field}"
        value = config.get(key)
        if value is not None and value != "":
            context[field] = value
    return context


def update_third_login_context(context: dict):
    """Merge third login context into local config."""
    config = load_config()
    for field in THIRD_LOGIN_CONTEXT_FIELDS:
        if field not in context:
            continue
        key = f"{THIRD_LOGIN_CONTEXT_PREFIX}{field}"
        value = context[field]
        if value is None:
            config.pop(key, None)
        else:
            config[key] = value
    save_config(config)


def clear_third_login_context():
    """Clear stored third login context."""
    config = load_config()
    for field in THIRD_LOGIN_CONTEXT_FIELDS:
        config.pop(f"{THIRD_LOGIN_CONTEXT_PREFIX}{field}", None)
    save_config(config)


def clear_config():
    """Clear stored configuration."""
    save_config({})
